import { useMemo } from 'react';
import { Slide, PillarId } from '@/types/index';
import { CanvasElement } from '@/types/canvas-elements';
import { getPillarTheme } from '@/config/pillars';
import { getStyleTemplate } from '@/config/styles';
import { domToCanvas } from '@/lib/canvas/dom-canvas-translation';

/**
 * useCanvasElements - Computed migration hook
 *
 * Phase 3 Refactor: Single Source of Truth Architecture
 *
 * This hook computes canvas elements from slide data on-demand.
 * Elements are NOT stored in state - they are computed whenever the slide changes.
 *
 * This approach provides:
 * - Single source of truth (carousel-store)
 * - No data duplication
 * - No sync complexity
 * - Automatic persistence (via carousel-store)
 * - Position mode preservation (Phase 3)
 * - Style override support (Phase 3)
 *
 * @param slide - Slide data from carousel-store
 * @param pillar - Pillar ID for theme styling
 * @param subTypeConfig - Sub-type configuration
 * @param decoratorConfig - Decorator configuration
 * @returns Computed array of canvas elements
 *
 * @example
 * ```tsx
 * const canvasElements = useCanvasElements(slide, pillar, subTypeConfig, decoratorConfig);
 *
 * // Render elements
 * canvasElements.map(element => renderElement(element));
 * ```
 */
export function useCanvasElements(
  slide: Slide,
  pillar: PillarId,
  subTypeConfig: any,
  decoratorConfig: any
): CanvasElement[] {
  // Get theme and style template
  const theme = getPillarTheme(pillar);
  const styleTemplate = getStyleTemplate(slide.style?.template || 'minimal') || getStyleTemplate('minimal')!;

  // Computed migration (no state change)
  // Elements are computed from slide data on-demand
  const canvasElements = useMemo(() => {
    console.log('[useCanvasElements] Computing canvas elements for slide:', slide.id);

    // Phase 3: Use domToCanvas translation function
    // This preserves position mode tags and respects useTheme flag
    const translationResult = domToCanvas(
      slide,
      theme,
      styleTemplate,
      subTypeConfig,
      decoratorConfig,
      {
        preserveMode: true,    // Preserve position mode through translation
        applyTheme: true,      // Apply theme styling
        extractOverrides: true, // Extract style overrides
        smartDetection: true,  // Use smart position detection
      }
    );

    const elements = translationResult.content as CanvasElement[];

    console.log('[useCanvasElements] Computed', elements.length, 'canvas elements');
    console.log('[useCanvasElements] Mode preserved:', translationResult.metadata.modePreserved);
    console.log('[useCanvasElements] Conflicts resolved:', translationResult.metadata.conflictsResolved);

    if (translationResult.metadata.warnings.length > 0) {
      console.warn('[useCanvasElements] Warnings:', translationResult.metadata.warnings);
    }

    return elements;
  }, [slide, theme, styleTemplate, subTypeConfig, decoratorConfig]);

  return canvasElements;
}

/**
 * useCanvasElementsSimple - Simplified version for basic usage
 *
 * This version automatically fetches sub-type configuration.
 *
 * @param slide - Slide data from carousel-store
 * @param pillar - Pillar ID for theme styling
 * @returns Computed array of canvas elements
 *
 * @example
 * ```tsx
 * const canvasElements = useCanvasElementsSimple(slide, pillar);
 * ```
 */
export function useCanvasElementsSimple(slide: Slide, pillar: PillarId): CanvasElement[] {
  // Get sub-type configuration
  const getDefaultSubTypeForSlideType = require('@/types/slide-subtypes').getDefaultSubTypeForSlideType;
  const getSubType = require('@/config/slide-subtypes').getSubType;
  const subTypeConfig = getSubType(slide.subType || getDefaultSubTypeForSlideType(slide.type));

  // Get decorator config hook
  const { useDecoratorConfig } = require('@/hooks/useDecoratorConfig');
  const { config: decoratorConfig } = useDecoratorConfig({
    pillarId: pillar,
    slideConfig: slide.style?.decoratorConfig,
    styleTemplateId: slide.style?.template,
    applyTemplateSuggestions: true,
  });

  return useCanvasElements(slide, pillar, subTypeConfig, decoratorConfig);
}