'use client';

import React, { useMemo, useCallback, useRef } from 'react';
import { Stage, Layer } from 'react-konva';
import { Slide, PillarId, SlideContent } from '@/types/index';
import { getDefaultSubTypeForSlideType } from '@/types/slide-subtypes';
import { SLIDE_WIDTH, SLIDE_HEIGHT } from '@/config/constants';
import { useDecoratorConfig } from '@/hooks/useDecoratorConfig';
import { useCanvasStore } from '@/store/canvas-store';
import { useCarouselStore } from '@/store/carousel-store';
import { useCanvasElements } from '@/hooks/useCanvasElements';
import { CanvasElement, TextElementData, ImageElementData } from '@/types/canvas-elements';
import { TextElement } from '@/canvas-editor/elements/TextElement';
import { ImageElement } from '@/canvas-editor/elements/ImageElement';
import { BackgroundElement } from '@/canvas-editor/elements/BackgroundElement';
import { DecoratorElement } from '@/canvas-editor/elements/DecoratorElement';
import { CTAElement } from '@/canvas-editor/elements/CTAElement';
import {
  canvasToDomPosition,
  getDefaultYPosition,
  preserveRotation,
} from '@/lib/canvas/position-translation';

interface CanvasSlideProps {
  slide: Slide;
  pillar: PillarId;
  carouselTotalSlides?: number;
  carouselBackgroundPack?: string;
  carouselDecoratorConfig?: any;
  isPreview?: boolean;
  scale?: number;
  onElementsChange?: (elements: CanvasElement[]) => void; // Phase 4: Expose elements to parent
  onElementDelete?: (elementId: string) => void; // Phase 4: Handle element deletion
}

/**
 * Convert canvas element to slide content
 *
 * Converts a single canvas element update to slide content format.
 * This is used for immediate sync when elements are updated in canvas mode.
 *
 * Phase 2 Enhancement: Uses smart position detection to preserve positioning intent.
 * - Auto-layout elements stay auto-layout when at center/edge positions
 * - Absolute positioning preserved for custom positions
 * - Rotation preserved through conversion
 *
 * @param element - Canvas element to convert
 * @param originalPosition - Original DOM position (if available) for mode preservation
 * @returns Slide content update or null if not applicable
 */
function convertCanvasElementToSlideContent(
  element: CanvasElement,
  originalPosition?: any
): Partial<SlideContent> | null {
  // Calculate position using smart detection
  const position = canvasToDomPosition(
    {
      x: element.x,
      y: element.y,
      width: element.width,
      height: element.height,
      rotation: preserveRotation(element.rotation),
    },
    originalPosition
  );

  // Only sync text and image elements (background, decorator, CTA are handled separately)
  if (element.type === 'text') {
    const textData = element.data as TextElementData;

    if (element.name === 'Headline') {
      return {
        headline: {
          value: textData.content,
          position,
        },
      };
    } else if (element.name === 'Subtext') {
      return {
        subtext: {
          value: textData.content,
          position,
        },
      };
    } else if (element.name === 'Bullets') {
      // Parse bullets from content
      const bulletLines = textData.content.split('\n');
      const bullets = bulletLines.map(line =>
        line.replace(/^[•\-*]\s*/, '').trim()
      ).filter(line => line.length > 0);

      return {
        bullets: {
          value: bullets,
          position,
        },
      };
    } else if (element.name === 'Quote') {
      // Remove quote marks
      const quoteValue = textData.content.replace(/^"|"$/g, '');
      return {
        quote: {
          value: quoteValue,
          position,
        },
      };
    } else if (element.name === 'Attribution') {
      // Remove dash
      const attributionValue = textData.content.replace(/^-\s*/, '');
      return {
        attribution: {
          value: attributionValue,
          position,
        },
      };
    }
  } else if (element.type === 'image') {
    const imageData = element.data as ImageElementData;

    return {
      imageConfig: {
        imageUrl: imageData.url,
        position: 'half-right', // Canvas mode uses free positioning, map to half-right
        size: (element.width / SLIDE_WIDTH) * 100, // Convert to percentage
        rotation: preserveRotation(element.rotation),
        opacity: element.opacity,
        objectFit: imageData.objectFit,
        filters: {
          blur: imageData.filters.blur,
          grayscale: imageData.filters.grayscale,
          sepia: imageData.filters.sepia,
          saturate: imageData.filters.saturate,
          brightness: imageData.filters.brightness,
          contrast: imageData.filters.contrast,
        },
        borderRadius: imageData.borderRadius,
        borderWidth: imageData.borderWidth,
        borderColor: imageData.borderColor,
        shadow: imageData.shadow,
        blendMode: imageData.blendMode as 'normal' | 'multiply' | 'screen' | 'overlay' | 'darken' | 'lighten' | 'color-dodge' | 'color-burn' | 'hard-light' | 'soft-light' | 'difference' | 'exclusion' | 'hue' | 'saturation' | 'color' | 'luminosity',
      },
    };
  }

  // Note: background, decorator, and CTA are not synced here as they are
  // managed through slide.style and slide.cta properties
  return null;
}

/**
 * CanvasSlide - Canvas-based slide rendering component
 *
 * Phase 3 Refactor: Single Source of Truth Architecture
 * Phase 4: Added comprehensive edge case handling
 *
 * This component renders a slide using Konva canvas instead of DOM elements.
 * Elements are computed from slide data (carousel-store) and rendered directly.
 *
 * Architecture Changes:
 * - Elements are computed from slide data (useCanvasElements hook)
 * - No elements state in canvas-store
 * - Canvas updates write directly to carousel-store
 * - No migration effects (elements are computed on-demand)
 * - Two-way sync is immediate (no debouncing needed)
 *
 * Edge Case Handling:
 * - Missing slide data: Shows error message
 * - Missing theme/template: Uses defaults
 * - Migration errors: Shows error message
 * - Empty slides: Shows placeholder message
 * - Invalid element data: Logs warning, skips element
 *
 * Features:
 * - Converts slide data to canvas elements (computed on-demand)
 * - Renders all element types (text, image, background, decorator, CTA)
 * - Supports all slide types (title, content, bullets, quote, cta, image)
 * - Maintains pillar theme styling
 * - Supports background packs
 * - Supports decorator configuration
 * - Single source of truth (carousel-store)
 * - Seamless mode switching (no data loss)
 * - Comprehensive error handling
 */
export const CanvasSlide: React.FC<CanvasSlideProps> = ({
  slide,
  pillar,
  carouselTotalSlides,
  carouselBackgroundPack,
  carouselDecoratorConfig,
  isPreview = false,
  scale = 1,
  onElementsChange,
  onElementDelete,
}) => {
  // Edge Case: Missing slide data
  if (!slide) {
    console.error('[CanvasSlide] No slide data provided');
    return (
      <div className="flex items-center justify-center w-full h-full bg-gray-100 text-gray-500">
        <div className="text-center">
          <p className="text-lg font-semibold">No slide data</p>
          <p className="text-sm">Please select a slide to edit</p>
        </div>
      </div>
    );
  }

  // Edge Case: Invalid slide ID
  if (!slide.id) {
    console.error('[CanvasSlide] Slide missing ID:', slide);
    return (
      <div className="flex items-center justify-center w-full h-full bg-red-50 text-red-500">
        <div className="text-center">
          <p className="text-lg font-semibold">Invalid slide data</p>
          <p className="text-sm">Slide is missing required ID</p>
        </div>
      </div>
    );
  }

  // Store updateSlide in ref to keep dependency array stable
  const { updateSlide } = useCarouselStore();
  const updateSlideRef = useRef(updateSlide);
  updateSlideRef.current = updateSlide;

  // Get selection state from canvas store (UI state only)
  const { selectedIds } = useCanvasStore();

  // Track local element state (for rendering)
  // Stores partial updates to elements (user edits that haven't been synced yet)
  const localElementsRef = useRef<Map<string, Partial<CanvasElement>>>(new Map());

  // Get sub-type configuration
  const { getSubType } = require('@/config/slide-subtypes');
  const subTypeConfig = getSubType(slide.subType || getDefaultSubTypeForSlideType(slide.type));

  // Use unified decorator config system
  const { config: decoratorConfig } = useDecoratorConfig({
    carouselConfig: carouselDecoratorConfig,
    pillarId: pillar,
    slideConfig: slide.style?.decoratorConfig,
    styleTemplateId: slide.style?.template,
    applyTemplateSuggestions: true,
  });

  // Compute canvas elements from slide data (single source of truth)
  // Edge Case: Wrap in try-catch to handle migration errors
  let computedElements: CanvasElement[] = [];
  let migrationError: Error | null = null;

  try {
    computedElements = useCanvasElements(slide, pillar, subTypeConfig, decoratorConfig);
  } catch (error) {
    migrationError = error instanceof Error ? error : new Error(String(error));
    console.error('[CanvasSlide] Migration failed:', migrationError);
  }

  // Merge computed elements with local modifications
  // This preserves user edits while keeping sync with slide data
  const elements = useMemo(() => {
    const merged = new Map<string, CanvasElement>();

    // Start with computed elements
    computedElements.forEach((element) => {
      // Edge Case: Skip invalid elements
      if (!element || !element.id || !element.type) {
        console.warn('[CanvasSlide] Skipping invalid element:', element);
        return;
      }

      merged.set(element.id, element);
    });

    // Apply local modifications (user edits)
    localElementsRef.current.forEach((element, id) => {
      if (merged.has(id)) {
        // Merge local modifications with computed element
        merged.set(id, { ...merged.get(id)!, ...element });
      }
    });

    // Phase 4: Expose elements to parent (PropertyPanel, LayerPanel)
    if (onElementsChange) {
      const elementsArray = Array.from(merged.values());
      onElementsChange(elementsArray);
    }

    return merged;
  }, [computedElements, onElementsChange]);

  // Handle element update (writes to carousel-store)
  const handleElementUpdate = useCallback((elementId: string, updates: Partial<CanvasElement>) => {
    console.log('[CanvasSlide] Element update:', elementId, updates);

    // Edge Case: Invalid element ID
    if (!elementId) {
      console.warn('[CanvasSlide] Element update called with invalid element ID');
      return;
    }

    // Update local state (for immediate feedback)
    // Note: We store partial updates and merge them when computing elements
    const existingUpdate = localElementsRef.current.get(elementId) || {};
    localElementsRef.current.set(elementId, { ...existingUpdate, ...updates } as Partial<CanvasElement>);

    // Convert canvas update to slide update
    const element = elements.get(elementId);
    if (!element) {
      console.warn('[CanvasSlide] Element not found:', elementId);
      return;
    }

    // Edge Case: Skip updates in preview mode
    if (isPreview) {
      console.log('[CanvasSlide] Skipping update in preview mode');
      return;
    }

    // Edge Case: Skip empty updates
    if (!updates || Object.keys(updates).length === 0) {
      console.warn('[CanvasSlide] Skipping empty update');
      return;
    }

    try {
      const updatedElement = { ...element, ...updates };

      // Get original position for mode preservation
      let originalPosition: any = undefined;
      const elementName = element.name;
      if (elementName && slide.content) {
        // Map element name to content field
        const contentFieldMap: Record<string, keyof SlideContent> = {
          'Headline': 'headline',
          'Subtext': 'subtext',
          'Bullets': 'bullets',
          'Quote': 'quote',
          'Attribution': 'attribution',
        };

        const field = contentFieldMap[elementName];
        if (field) {
          const content = slide.content[field];
          if (content && typeof content === 'object' && 'position' in content) {
            originalPosition = (content as any).position;
          }
        }
      }

      const slideContent = convertCanvasElementToSlideContent(updatedElement, originalPosition);

      // Write to carousel-store (single source of truth)
      if (slideContent) {
        console.log('[CanvasSlide] Writing to carousel-store:', slide.id, slideContent);
        updateSlideRef.current(slide.id, slideContent);
      }
    } catch (error) {
      console.error('[CanvasSlide] Error updating slide:', error);
      // Don't throw - let the user continue editing
    }
  }, [elements, slide.id, isPreview, slide.content]);

  // Phase 4: Handle element deletion
  const handleElementDelete = useCallback((elementId: string) => {
    console.log('[CanvasSlide] Element delete:', elementId);

    // Edge Case: Invalid element ID
    if (!elementId) {
      console.warn('[CanvasSlide] Element delete called with invalid element ID');
      return;
    }

    // Edge Case: Skip deletion in preview mode
    if (isPreview) {
      console.log('[CanvasSlide] Skipping delete in preview mode');
      return;
    }

    const element = elements.get(elementId);
    if (!element) {
      console.warn('[CanvasSlide] Element not found for deletion:', elementId);
      return;
    }

    // Map element name to content field
    const contentFieldMap: Record<string, keyof SlideContent> = {
      'Headline': 'headline',
      'Subtext': 'subtext',
      'Bullets': 'bullets',
      'Quote': 'quote',
      'Attribution': 'attribution',
    };

    const field = contentFieldMap[element.name];
    if (field) {
      // Clear the content field to delete the element
      updateSlideRef.current(slide.id, { [field]: undefined });
    } else {
      console.warn('[CanvasSlide] Cannot delete element type:', element.name);
    }

    // Call parent callback if provided
    if (onElementDelete) {
      onElementDelete(elementId);
    }
  }, [elements, slide.id, isPreview, onElementDelete]);

  // Phase 4: Expose functions via onElementsChange callback
  // We'll pass the current elements AND the update/delete functions
  if (onElementsChange) {
    const elementsArray = Array.from(elements.values());
    onElementsChange(elementsArray);
  }

  // Get sorted elements by zIndex
  const sortedElements = Array.from(elements.values()).sort((a, b) => a.zIndex - b.zIndex);

  // Handle element selection
  const handleElementSelect = useCallback((elementId: string) => {
    if (!isPreview) {
      const { selectElement } = useCanvasStore.getState();
      selectElement(elementId, false);
    }
  }, [isPreview]);

  // Handle element transform
  const handleElementTransform = useCallback((elementId: string) => (transform: any) => {
    console.log('[CanvasSlide] Transform called for', elementId, ':', transform);
    handleElementUpdate(elementId, transform);
  }, [handleElementUpdate]);

  // Render element based on type
  const renderElement = (element: CanvasElement) => {
    // Edge Case: Skip invalid elements
    if (!element || !element.id || !element.type) {
      console.warn('[CanvasSlide] Skipping invalid element in render:', element);
      return null;
    }

    const isSelected = selectedIds.includes(element.id);
    const onSelect = handleElementSelect;
    const onTransform = handleElementTransform(element.id);

    try {
      switch (element.type) {
        case 'text':
          return (
            <TextElement
              key={element.id}
              element={element}
              isSelected={isSelected}
              onSelect={onSelect}
              onTransform={onTransform}
            />
          );

        case 'image':
          return (
            <ImageElement
              key={element.id}
              element={element}
              isSelected={isSelected}
              onSelect={onSelect}
              onTransform={onTransform}
            />
          );

        case 'background':
          return (
            <BackgroundElement
              key={element.id}
              element={element}
              isSelected={isSelected}
              onSelect={onSelect}
              onTransform={onTransform}
            />
          );

        case 'decorator':
          return (
            <DecoratorElement
              key={element.id}
              element={element}
              isSelected={isSelected}
              onSelect={onSelect}
              onTransform={onTransform}
            />
          );

        case 'cta':
          return (
            <CTAElement
              key={element.id}
              element={element}
              isSelected={isSelected}
              onSelect={onSelect}
              onTransform={onTransform}
            />
          );

        default:
          console.warn(`[CanvasSlide] Unknown element type: ${element.type}`);
          return null;
      }
    } catch (error) {
      console.error(`[CanvasSlide] Error rendering element ${element.id}:`, error);
      return null;
    }
  };

  // Edge Case: Migration error display
  if (migrationError) {
    return (
      <div className="flex items-center justify-center w-full h-full bg-red-50 text-red-500">
        <div className="text-center">
          <p className="text-lg font-semibold">Migration failed</p>
          <p className="text-sm">{migrationError.message}</p>
          <p className="text-xs mt-2">Please check the console for details</p>
        </div>
      </div>
    );
  }

  // Edge Case: Empty slide (no elements)
  if (sortedElements.length === 0) {
    return (
      <Stage
        width={SLIDE_WIDTH * scale}
        height={SLIDE_HEIGHT * scale}
        scaleX={scale}
        scaleY={scale}
        className="canvas-slide"
      >
        <Layer>
          <div className="flex items-center justify-center w-full h-full text-gray-400 text-sm">
            <p>No elements to display</p>
          </div>
        </Layer>
      </Stage>
    );
  }

  return (
    <Stage
      width={SLIDE_WIDTH * scale}
      height={SLIDE_HEIGHT * scale}
      scaleX={scale}
      scaleY={scale}
      className="canvas-slide"
    >
      <Layer>
        {sortedElements.map((element: CanvasElement) => renderElement(element))}
      </Layer>
    </Stage>
  );
};

/**
 * CanvasSlidePreview - Preview variant of CanvasSlide
 *
 * This is a convenience component for previewing slides without editing capabilities.
 */
interface CanvasSlidePreviewProps {
  slide: Slide;
  pillar: PillarId;
  carouselTotalSlides?: number;
  carouselBackgroundPack?: string;
  carouselDecoratorConfig?: any;
  scale?: number;
}

export const CanvasSlidePreview: React.FC<CanvasSlidePreviewProps> = (props) => {
  return <CanvasSlide {...props} isPreview={true} />;
};

/**
 * CanvasSlideEditor - Editor variant of CanvasSlide
 *
 * This is a convenience component for editing slides with full interactivity.
 */
interface CanvasSlideEditorProps {
  slide: Slide;
  pillar: PillarId;
  carouselTotalSlides?: number;
  carouselBackgroundPack?: string;
  carouselDecoratorConfig?: any;
  scale?: number;
}

export const CanvasSlideEditor: React.FC<CanvasSlideEditorProps> = (props) => {
  return <CanvasSlide {...props} isPreview={false} />;
};