/**
 * DOM/Canvas Translation Module
 *
 * Provides bidirectional translation between DOM mode and Canvas mode.
 * This module implements Phase 3 of the DOM/Canvas integration plan.
 *
 * Key Features:
 * - domToCanvas(): Convert DOM slide content to Canvas elements
 * - canvasToDom(): Convert Canvas elements to DOM slide content
 * - Conflict resolution (theme vs. overrides)
 * - Round-trip preservation
 *
 * Translation Flow:
 * DOM Mode → Canvas Mode: Uses migration functions + position translation
 * Canvas Mode → DOM Mode: Uses smart detection + style extraction
 */

import { Slide, SlideContent } from '@/types/slide';
import { CanvasElement } from '@/types/canvas-elements';
import { ElementPosition, ContentStyle, getContentValue, getContentPosition, getContentStyle } from '@/types/slide-subtypes';
import { migrateSlideToCanvas } from './element-migration';
import { domToCanvasPosition, canvasToDomPosition, CanvasElementPosition } from './position-translation';

/**
 * Translation options for controlling behavior
 */
export interface TranslationOptions {
  /**
   * Preserve mode tags through translation
   * @default true
   */
  preserveMode?: boolean;

  /**
   * Apply theme styling to elements
   * @default true
   */
  applyTheme?: boolean;

  /**
   * Extract style overrides from canvas elements
   * @default true
   */
  extractOverrides?: boolean;

  /**
   * Use smart position detection
   * @default true
   */
  smartDetection?: boolean;
}

/**
 * Translation result with metadata
 */
export interface TranslationResult {
  /**
   * Translated content
   */
  content: Partial<SlideContent> | CanvasElement[];

  /**
   * Translation metadata
   */
  metadata: {
    /**
     * Number of elements translated
     */
    elementCount: number;

    /**
     * Number of conflicts resolved
     */
    conflictsResolved: number;

    /**
     * Whether mode was preserved
     */
    modePreserved: boolean;

    /**
     * Translation warnings
     */
    warnings: string[];
  };
}

/**
 * Convert DOM slide content to Canvas elements
 *
 * This function translates DOM slide content (from carousel-store) to Canvas elements
 * for rendering in Canvas mode. It preserves positioning intent and styling.
 *
 * @param slide - The slide to translate
 * @param theme - Pillar theme configuration
 * @param styleTemplate - Style template configuration
 * @param subTypeConfig - Sub-type configuration
 * @param decoratorConfig - Decorator configuration
 * @param options - Translation options
 * @returns Translation result with Canvas elements
 *
 * @example
 * ```typescript
 * const result = domToCanvas(
 *   slide,
 *   theme,
 *   styleTemplate,
 *   subTypeConfig,
 *   decoratorConfig,
 *   { preserveMode: true, applyTheme: true }
 * );
 *
 * console.log(`Translated ${result.metadata.elementCount} elements`);
 * console.log(`Mode preserved: ${result.metadata.modePreserved}`);
 * ```
 */
export function domToCanvas(
  slide: Slide,
  theme: any,
  styleTemplate: any,
  subTypeConfig: any,
  decoratorConfig: any,
  options: TranslationOptions = {}
): TranslationResult {
  const warnings: string[] = [];
  let conflictsResolved = 0;

  // Apply default options
  const opts = {
    preserveMode: options.preserveMode ?? true,
    applyTheme: options.applyTheme ?? true,
    extractOverrides: options.extractOverrides ?? true,
    smartDetection: options.smartDetection ?? true,
  };

  // Migrate slide to canvas using existing migration function
  // This function already respects the useTheme flag (Phase 1)
  let canvasElements = migrateSlideToCanvas(
    slide,
    opts.applyTheme ? theme : undefined,
    styleTemplate,
    subTypeConfig,
    decoratorConfig
  );

  // Enhance canvas elements with position mode tags if preserveMode is enabled
  if (opts.preserveMode) {
    canvasElements = canvasElements.map(element => {
      // Skip background, decorators, and locked elements
      if (element.locked || element.type === 'background' || element.type === 'decorator') {
        return element;
      }

      // Only process text elements (headline, subtext, bullets, quote, attribution)
      if (element.type !== 'text') {
        return element;
      }

      // Get element ID to determine which content field it represents
      const elementId = element.id;
      const contentType = elementId.split('-').pop() as 'headline' | 'subtext' | 'bullets' | 'quote' | 'attribution';

      if (!contentType) {
        return element;
      }

      // Get position from slide content
      let position: ElementPosition | undefined;
      if (contentType === 'headline') {
        position = getContentPosition(slide.content.headline);
      } else if (contentType === 'subtext') {
        position = getContentPosition(slide.content.subtext);
      } else if (contentType === 'bullets') {
        position = getContentPosition(slide.content.bullets);
      } else if (contentType === 'quote') {
        position = getContentPosition(slide.content.quote);
      } else if (contentType === 'attribution') {
        position = getContentPosition(slide.content.attribution);
      }

      // Skip if no position
      if (!position) {
        return element;
      }

      // Convert DOM position to Canvas position
      const canvasPosition = domToCanvasPosition(
        position,
        element.width,
        element.height,
        element.y // Use current Y as default
      );

      // Update element with position mode tags
      return {
        ...element,
        _mode: canvasPosition._mode,
        _alignment: canvasPosition._alignment,
        _originalPosition: position, // Store original position for round-trip
      } as CanvasElement & { _mode?: string; _alignment?: string; _originalPosition?: ElementPosition };
    });
  }

  // Build result metadata
  const metadata = {
    elementCount: canvasElements.length,
    conflictsResolved,
    modePreserved: opts.preserveMode,
    warnings,
  };

  return {
    content: canvasElements,
    metadata,
  };
}

/**
 * Convert Canvas elements to DOM slide content
 *
 * This function translates Canvas elements (from Canvas mode) to DOM slide content
 * for storage in carousel-store. It uses smart detection to preserve positioning intent
 * and extracts style overrides.
 *
 * @param elements - Canvas elements to translate
 * @param slide - Original slide (for reference)
 * @param options - Translation options
 * @returns Translation result with slide content
 *
 * @example
 * ```typescript
 * const result = canvasToDom(
 *   canvasElements,
 *   slide,
 *   { smartDetection: true, extractOverrides: true }
 * );
 *
 * console.log(`Translated ${result.metadata.elementCount} elements`);
 * console.log(`Mode preserved: ${result.metadata.modePreserved}`);
 *
 * // Update slide content
 * if (result.content.headline) {
 *   updateSlide(slide.id, { headline: result.content.headline });
 * }
 * ```
 */
export function canvasToDom(
  elements: CanvasElement[],
  slide: Slide,
  options: TranslationOptions = {}
): TranslationResult {
  const warnings: string[] = [];
  let conflictsResolved = 0;
  const contentUpdates: Partial<SlideContent> = {};

  // Apply default options
  const opts = {
    preserveMode: options.preserveMode ?? true,
    applyTheme: options.applyTheme ?? true,
    extractOverrides: options.extractOverrides ?? true,
    smartDetection: options.smartDetection ?? true,
  };

  // Process each canvas element
  for (const element of elements) {
    // Skip background, decorators, and locked elements
    if (element.locked || element.type === 'background' || element.type === 'decorator') {
      continue;
    }

    // Only process text elements (headline, subtext, bullets, quote, attribution)
    if (element.type !== 'text') {
      continue;
    }

    // Get element ID to determine which content field it represents
    const elementId = element.id;
    const contentType = elementId.split('-').pop() as 'headline' | 'subtext' | 'bullets' | 'quote' | 'attribution';

    if (!contentType) {
      warnings.push(`Unknown element type for ID: ${elementId}`);
      continue;
    }

    // Get original position from element metadata (if available)
    const originalPosition = (element as any)._originalPosition as ElementPosition | undefined;

    // Get current position from element
    const currentPosition: CanvasElementPosition = {
      x: element.x,
      y: element.y,
      width: element.width,
      height: element.height,
      rotation: element.rotation,
    };

    // Convert Canvas position to DOM position using smart detection
    let domPosition: ElementPosition;

    if (opts.smartDetection && opts.preserveMode) {
      // Use smart detection to preserve positioning intent
      domPosition = canvasToDomPosition(currentPosition, originalPosition);
    } else {
      // Force absolute positioning (fallback)
      domPosition = canvasToDomPosition(currentPosition, undefined);
    }

    // Extract style overrides if enabled
    let styleOverrides: ContentStyle | undefined;

    if (opts.extractOverrides) {
      // Check if element has custom styling (useTheme flag is false)
      const elementData = element.data as any;
      const useTheme = elementData._useTheme ?? true;

      if (!useTheme) {
        // Extract style overrides from element data
        styleOverrides = {
          fontSize: elementData.fontSize,
          fontFamily: elementData.fontFamily,
          fontWeight: elementData.fontWeight,
          color: elementData.color,
          lineHeight: elementData.lineHeight,
          letterSpacing: elementData.letterSpacing,
          fontStyle: elementData.fontStyle,
          textDecoration: elementData.textDecoration,
          useTheme: false, // Explicitly set to false
        };
      } else {
        // Preserve useTheme: true if it was true
        styleOverrides = {
          useTheme: true,
        };
      }
    }

    // Get content value from element data
    const elementData = element.data as any;
    let contentValue = elementData.content;

    // Format content based on type
    if (contentType === 'bullets') {
      // Split bullets by newline
      contentValue = contentValue.split('\n').map((bullet: string) => {
        // Remove bullet point prefix if present
        return bullet.replace(/^[•\-\*]\s*/, '').trim();
      });
    } else if (contentType === 'quote') {
      // Remove quote marks if present
      contentValue = contentValue.replace(/^"|"$/g, '');
    } else if (contentType === 'attribution') {
      // Remove dash prefix if present
      contentValue = contentValue.replace(/^-\s*/, '');
    }

    // Build positioned content
    const positionedContent: any = {
      value: contentValue,
      position: domPosition,
    };

    // Add style overrides if available
    if (styleOverrides && Object.keys(styleOverrides).length > 0) {
      positionedContent.style = styleOverrides;
    }

    // Update content based on type
    switch (contentType) {
      case 'headline':
        contentUpdates.headline = positionedContent;
        break;
      case 'subtext':
        contentUpdates.subtext = positionedContent;
        break;
      case 'bullets':
        contentUpdates.bullets = positionedContent;
        break;
      case 'quote':
        contentUpdates.quote = positionedContent;
        break;
      case 'attribution':
        contentUpdates.attribution = positionedContent;
        break;
      default:
        warnings.push(`Unhandled content type: ${contentType}`);
    }
  }

  // Build result metadata
  const metadata = {
    elementCount: Object.keys(contentUpdates).length,
    conflictsResolved,
    modePreserved: opts.preserveMode,
    warnings,
  };

  return {
    content: contentUpdates,
    metadata,
  };
}

/**
 * Resolve style conflicts between theme and overrides
 *
 * This function determines which styling should be applied when there's a conflict
 * between theme-based styling and custom overrides.
 *
 * @param themeStyle - Theme-based styling
 * @param overrideStyle - Custom override styling
 * @param useTheme - Whether to use theme styling
 * @returns Resolved styling
 *
 * @example
 * ```typescript
 * const themeStyle = { fontSize: 64, color: '#00E5FF' };
 * const overrideStyle = { fontSize: 72, color: '#FF0000' };
 *
 * // useTheme: true → Use theme style
 * const resolved1 = resolveStyleConflict(themeStyle, overrideStyle, true);
 * // { fontSize: 64, color: '#00E5FF' }
 *
 * // useTheme: false → Use override style
 * const resolved2 = resolveStyleConflict(themeStyle, overrideStyle, false);
 * // { fontSize: 72, color: '#FF0000' }
 * ```
 */
export function resolveStyleConflict(
  themeStyle: Partial<ContentStyle>,
  overrideStyle: Partial<ContentStyle>,
  useTheme: boolean
): Partial<ContentStyle> {
  if (useTheme) {
    // Use theme styling, but allow specific overrides if provided
    return {
      ...themeStyle,
      useTheme: true,
    };
  } else {
    // Use override styling
    return {
      ...overrideStyle,
      useTheme: false,
    };
  }
}

/**
 * Validate translation result
 *
 * Checks if the translation result is valid and returns any issues.
 *
 * @param result - Translation result to validate
 * @returns Validation result with issues
 *
 * @example
 * ```typescript
 * const result = domToCanvas(slide, theme, styleTemplate, ...);
 * const validation = validateTranslationResult(result);
 *
 * if (validation.hasIssues) {
 *   console.error('Translation failed:', validation.issues);
 * }
 * ```
 */
export function validateTranslationResult(result: TranslationResult): {
  isValid: boolean;
  hasIssues: boolean;
  issues: string[];
} {
  const issues: string[] = [];

  // Check for warnings
  if (result.metadata.warnings.length > 0) {
    issues.push(...result.metadata.warnings);
  }

  // Check if any elements were translated
  if (result.metadata.elementCount === 0) {
    issues.push('No elements were translated');
  }

  // Check for conflicts
  if (result.metadata.conflictsResolved > 0) {
    issues.push(`${result.metadata.conflictsResolved} conflicts were resolved`);
  }

  return {
    isValid: issues.length === 0,
    hasIssues: issues.length > 0,
    issues,
  };
}

/**
 * Round-trip test for translation
 *
 * Tests if content can be translated from DOM to Canvas and back to DOM
 * without data loss. This is useful for testing and validation.
 *
 * @param slide - Original slide
 * @param theme - Pillar theme configuration
 * @param styleTemplate - Style template configuration
 * @param subTypeConfig - Sub-type configuration
 * @param decoratorConfig - Decorator configuration
 * @returns Round-trip test result
 *
 * @example
 * ```typescript
 * const testResult = testRoundTrip(slide, theme, styleTemplate, ...);
 *
 * if (testResult.success) {
 *   console.log('Round-trip test passed!');
 * } else {
 *   console.error('Round-trip test failed:', testResult.issues);
 * }
 * ```
 */
export function testRoundTrip(
  slide: Slide,
  theme: any,
  styleTemplate: any,
  subTypeConfig: any,
  decoratorConfig: any
): {
  success: boolean;
  issues: string[];
  metadata: {
    domToCanvasElements: number;
    canvasToDomElements: number;
    modePreserved: boolean;
  };
} {
  const issues: string[] = [];

  // Step 1: DOM → Canvas
  const domToCanvasResult = domToCanvas(
    slide,
    theme,
    styleTemplate,
    subTypeConfig,
    decoratorConfig,
    { preserveMode: true, smartDetection: true }
  );

  const canvasElements = domToCanvasResult.content as CanvasElement[];

  // Step 2: Canvas → DOM
  const canvasToDomResult = canvasToDom(
    canvasElements,
    slide,
    { preserveMode: true, smartDetection: true }
  );

  const domContent = canvasToDomResult.content as Partial<SlideContent>;

  // Step 3: Compare original and round-trip content
  const originalContent = slide.content;
  const roundTripContent = domContent;

  // Check if all content fields are preserved
  const contentFields: (keyof SlideContent)[] = ['headline', 'subtext', 'bullets', 'quote', 'attribution'];

  for (const field of contentFields) {
    const originalValue = getContentValue((originalContent as any)[field]);
    const roundTripValue = getContentValue((roundTripContent as any)[field]);

    // Compare values (handle arrays for bullets)
    if (Array.isArray(originalValue) && Array.isArray(roundTripValue)) {
      if (JSON.stringify(originalValue) !== JSON.stringify(roundTripValue)) {
        issues.push(`${field} content mismatch after round-trip`);
      }
    } else if (originalValue !== roundTripValue) {
      issues.push(`${field} content mismatch after round-trip`);
    }
  }

  // Check if mode is preserved
  for (const field of contentFields) {
    const originalPosition = getContentPosition((originalContent as any)[field]);
    const roundTripPosition = getContentPosition((roundTripContent as any)[field]);

    if (originalPosition?.mode !== roundTripPosition?.mode) {
      issues.push(`${field} mode not preserved: ${originalPosition?.mode} → ${roundTripPosition?.mode}`);
    }
  }

  return {
    success: issues.length === 0,
    issues,
    metadata: {
      domToCanvasElements: domToCanvasResult.metadata.elementCount,
      canvasToDomElements: canvasToDomResult.metadata.elementCount,
      modePreserved: domToCanvasResult.metadata.modePreserved && canvasToDomResult.metadata.modePreserved,
    },
  };
}